 "content": "from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The full monochrome edge identifies the direction of gravity.
    if all(v == g[0][0] and v != 0 for v in g[0]):
        dr, dc = 1, 0
    elif all(v == g[-1][0] and v != 0 for v in g[-1]):
        dr, dc = -1, 0
    elif all(row[0] == g[0][0] and row[0] != 0 for row in g):
        dr, dc = 0, 1
    elif all(row[-1] == g[0][-1] and row[-1] != 0 for row in g):
        dr, dc = 0, -1
    else:
        raise ValueError('No solid edge identifies gravity')

    # Extract each 4-connected colored object, excluding the solid edge.
    barrier = set()
    if dr == 1: barrier = {(0, c) for c in range(w)}
    elif dr == -1: barrier = {(h-1, c) for c in range(w)}
    elif dc == 1: barrier = {(r, 0) for r in range(h)}
    else: barrier = {(r, w-1) for r in range(h)}
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 or (r,c) in barrier or (r,c) in seen:
                continue
            color = g[r][c]
            q = [(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and (yy,xx) not in barrier and g[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            objects.append((color,cells))

    # Move each object to rest, processing objects nearest the gravity edge first.
    def rank(obj):
        cells = obj[1]
        if dr == 1: return -max(r for r,c in cells)
        if dr == -1: return min(r for r,c in cells)
        if dc == 1: return -max(c for r,c in cells)
        return min(c for r,c in cells)
    objects.sort(key=rank)
    out = [[0]*w for _ in range(h)]
    for r,c in barrier: out[r][c] = g[r][c]
    for color,cells in objects:
        cells = list(cells)
        while True:
            shifted = [(r+dr,c+dc) for r,c in cells]
            if any(not (0 <= r < h and 0 <= c < w) or out[r][c] != 0 for r,c in shifted):
                break
            cells = shifted
        for r,c in cells: out[r][c] = color
    return out
